if set(fixed_cost.keys()) != set(suppliers):
    raise ValueError('Fixed cost data missing or extra suppliers.')
if set(demand.keys()) != set(supermarkets):
    raise ValueError('Demand data missing or extra supermarkets.')
if set(transportation_cost.keys()) != set(suppliers):
    raise ValueError('Transportation cost data missing or extra suppliers.')
for s in suppliers:
    if set(transportation_cost[s].keys()) != set(supermarkets):
        raise ValueError(f'Transportation cost data for {s} missing or extra supermarkets.')
m = Model()
m.Params.MIPGap = 0.0001
y_vars = m.addVars(suppliers, vtype=GRB.BINARY, lb=0, ub=1, name='')
x_vars = m.addVars(suppliers, supermarkets, vtype=GRB.CONTINUOUS, lb=0, name='')
for c in supermarkets:
    m.addConstr(quicksum((x_vars[s, c] for s in suppliers)) == demand[c], name='d_%s' % c)
for s in suppliers:
    for c in supermarkets:
        m.addConstr(x_vars[s, c] <= demand[c] * y_vars[s], name='link_%s_%s' % (s, c))
m.setObjective(quicksum((fixed_cost[s] * y_vars[s] for s in suppliers)) + quicksum((transportation_cost[s][c] * x_vars[s, c] for s in suppliers for c in supermarkets)), GRB.MINIMIZE)
m.optimize()
if m.Status == GRB.OPTIMAL:
    print('ObjVal', m.ObjVal)
    for v in m.getVars():
        print(v.VarName, v.X)
else:
    print('Status', m.Status)